const ANIMS=[
 {id:'idle',name:'Idle loop',rows:['idle'],loop:true,description:'Stand and breathe'},
 {id:'run',name:'Run',rows:['run'],loop:true,description:'Start frame into run loop'},
 {id:'jump',name:'Jump',rows:['jump'],loop:true,description:'Takeoff, rise, hang, fall, land'},
 {id:'dash',name:'Dash',rows:['dash'],loop:true,description:'Dash start, loop and skid stop'},
 {id:'combo',name:'3-hit saber combo',rows:['slash1','slash2','slash3'],loop:false,description:'Three chained ground slashes'},
 {id:'dashSlash',name:'Dash slash',rows:['dashSlash'],loop:false,description:'Saber slash while dashing'},
 {id:'airSlash',name:'Air slash',rows:['airSlash'],loop:false,description:'Mid-air saber attack'},
 {id:'risingSlash',name:'Rising slash',rows:['risingSlash','risingFall'],loop:false,description:'Up + Saber'},
 {id:'plunge',name:'Plunge',rows:['plunge'],loop:false,description:'Down + Saber in air'},
 {id:'busterIdle',name:'Buster — stand',rows:['busterIdle'],loop:false,description:'Standing shot pose'},
 {id:'runBuster',name:'Buster — run',rows:['runBuster'],loop:true,description:'Run and fire'},
 {id:'jumpBuster',name:'Buster — jump',rows:['jumpBuster'],loop:true,description:'Air shot pose'},
 {id:'dashBuster',name:'Buster — dash',rows:['dashBuster'],loop:true,description:'Dash and fire'},
 {id:'charge',name:'Charge shot + rings',rows:['charge'],loop:true,description:'Hold Buster to charge'},
 {id:'ready',name:'Saber ready pose',rows:['ready'],loop:true,description:'Tap T / Ready'},
 {id:'climb',name:'Ladder climb',rows:['climb'],loop:true,description:'Up near ladder'},
 {id:'ladderSlash',name:'Ladder slash',rows:['ladderSlash'],loop:false,description:'Saber while climbing'},
 {id:'effects',name:'Shots and hits',rows:['effects','bullets'],loop:true,description:'Projectile and hit effects'},
 {id:'chargeFx',name:'Charge rings',rows:['charge'],loop:true,description:'Charge ring effects'},
 {id:'bursts',name:'Hit bursts',rows:['bursts'],loop:true,description:'Impact effects'}
];
function refsFor(id){const def=ANIMS.find(a=>a.id===id);if(!def)return[];return def.rows.flatMap(row=>(frames[row]||[]).map((_,i)=>({row,index:i}))).filter(ref=>frames[ref.row]&&frames[ref.row][ref.index])}
function buildAnimationList(){const list=$('#animList');list.innerHTML='';for(const def of ANIMS){const b=document.createElement('button');b.className='anim-option'+(preview.id===def.id?' selected':'');b.innerHTML=`${def.name}<small>${def.description} · ${(refsFor(def.id)||[]).length} frames</small>`;b.addEventListener('click',()=>selectPreview(def.id));list.appendChild(b)}}
const preview={id:'idle',index:0,playing:true,ticks:0};
function selectPreview(id){preview.id=id;preview.index=0;preview.playing=true;preview.ticks=0;const def=ANIMS.find(a=>a.id===id);$('#previewName').textContent=def?`${def.name} · frame 1/${Math.max(1,refsFor(id).length)}`:'Choose an animation';buildAnimationList()}
$('#animationsOpen').addEventListener('click',()=>{$('#animModal').classList.add('open');buildAnimationList()});$('#animationsClose').addEventListener('click',()=>$('#animModal').classList.remove('open'));
$('#prevFrame').addEventListener('click',()=>{const n=refsFor(preview.id).length;preview.index=(preview.index+n-1)%Math.max(1,n);preview.playing=false});$('#nextFrame').addEventListener('click',()=>{const n=refsFor(preview.id).length;preview.index=(preview.index+1)%Math.max(1,n);preview.playing=false});$('#previewPlay').addEventListener('click',()=>{preview.playing=!preview.playing;$('#previewPlay').textContent=preview.playing?'PAUSE':'PLAY'});

