$('#previewPlay').addEventListener('click',()=>{preview.playing=!preview.playing;$('#previewPlay').textContent=preview.playing?'PAUSE':'PLAY'});
const held=new Set(),pressed=new Set(),sources=new Map(),keySource=new Set();
function setInput(source,action,down){const before=new Set(held);if(down){sources.set(source,action)}else sources.delete(source);held.clear();for(const a of sources.values())held.add(a);if(action&&down&&!before.has(action))pressed.add(action);if(action&&!down&&before.has(action)&&!held.has(action))onRelease(action)}
function onRelease(action){if(action==='buster'&&game.charge>0){game.shot=24;game.charge=0;if(!game.airborne&&!held.has('right')&&!held.has('left'))setAnim('busterIdle',18)}}
function bindTouch(){document.querySelectorAll('[data-action]').forEach(el=>{const action=el.dataset.action;el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);el.classList.add('active');setInput(`p${e.pointerId}`,action,true)},{passive:false});const end=e=>{if(e) e.preventDefault();el.classList.remove('active');setInput(`p${e.pointerId}`,action,false)};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('lostpointercapture',end)})}
bindTouch();
const keyMap={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down', ' ':'jump',z:'dash',Z:'dash',x:'saber',X:'saber',c:'buster',C:'buster',t:'ready',T:'ready'};
window.addEventListener('keydown',e=>{const a=keyMap[e.key];if(!a)return;e.preventDefault();if(!keySource.has(e.key)){keySource.add(e.key);setInput(`k${e.key}`,a,true)}});
window.addEventListener('keyup',e=>{const a=keyMap[e.key];if(!a)return;e.preventDefault();keySource.delete(e.key);setInput(`k${e.key}`,a,false)});
window.addEventListener('blur',()=>{for(const [id,a] of [...sources])setInput(id,a,false);keySource.clear()});
const game={x:105,feet:FLOOR,vy:0,airborne:false,facing:1,anim:'idle',animTick:0,stateTick:0,dashTicks:0,attackHit:0,comboQueued:0,charge:0,shot:0,ladder:false,ready:false};
function setAnim(id,duration=0){if(game.anim!==id){game.anim=id;game.animTick=0}if(duration)game.stateTick=duration}
function clampPlayer(){game.x=Math.max(27,Math.min(W-27,game.x));if(game.feet>=FLOOR){game.feet=FLOOR;game.vy=0;game.airborne=false}}
function beginSaber(){if(game.ladder){setAnim('ladderSlash');game.stateTick=24;return}if(game.dashTicks>0){setAnim('dashSlash');game.stateTick=21;return}if(game.airborne){if(held.has('up')){setAnim('risingSlash');game.vy=-5.8;game.stateTick=31}else if(held.has('down')){setAnim('plunge');game.vy=7.8;game.stateTick=25}else{setAnim('airSlash');game.stateTick=24}return}
 game.attackHit=1;game.comboQueued=0;setAnim('slash1');game.stateTick=Math.max(10,(frames.slash1||[]).length*4)}
function updateGame(){
 if(pressed.has('ready')){game.ready=!game.ready;setAnim(game.ready?'ready':'idle')}
 const left=held.has('left'),right=held.has('right'),move=(right?1:0)-(left?1:0);if(move)game.facing=move;
 if(pressed.has('jump')&&!game.airborne&&!game.ladder&&!game.anim.startsWith('slash')&&!game.anim.includes('Slash')){game.vy=-8.2;game.airborne=true;game.ready=false;setAnim('jump')}
 if(pressed.has('dash')&&game.dashTicks<=0){game.dashTicks=34;game.ready=false;game.facing=move||game.facing;setAnim('dash')}
 if(pressed.has('saber')){if(['slash1','slash2','slash3'].includes(game.anim)){if(game.attackHit<3)game.comboQueued=Math.min(3-game.attackHit,game.comboQueued+1)}else beginSaber()}
 if(held.has('buster'))game.charge=Math.min(90,game.charge+1);
 if(game.ladder&&held.has('up')){game.feet=Math.max(112,game.feet-1.6);if(game.anim!=='ladderSlash')setAnim('climb')}
 else if(game.airborne){game.vy=Math.min(8.5,game.vy+0.34);game.feet+=game.vy;if(game.anim==='risingSlash'&&game.vy>0)setAnim('risingFall');if(game.feet>=FLOOR){game.feet=FLOOR;game.vy=0;game.airborne=false;if(['jump','jumpBuster','risingFall','plunge'].includes(game.anim)){setAnim('idle');game.stateTick=0}}}
 if(game.dashTicks>0){game.dashTicks--;game.x+=game.facing*4.7;if(game.anim!=='dashSlash'&&game.anim!=='dashBuster')setAnim(held.has('buster')?'dashBuster':'dash');if(game.dashTicks===0&&game.anim==='dash')setAnim('idle')}
 else if(!game.ladder&&move){game.x+=move*(game.airborne?1.7:2.1);if(!game.airborne&&!['slash1','slash2','slash3','airSlash','risingSlash','risingFall','plunge','ladderSlash'].includes(game.anim))setAnim(held.has('buster')?'runBuster':'run')}
 if(pressed.has('up')&&Math.abs(game.x-408)<45&&!game.airborne){game.ladder=true;setAnim('climb')}
 if(game.ladder&&pressed.has('down')&&game.feet>=FLOOR-2){game.ladder=false;setAnim('idle')}
 if(game.shot>0)game.shot--;
 if(game.stateTick>0){game.stateTick--;if(game.stateTick===0){if(['slash1','slash2','slash3'].includes(game.anim)&&game.comboQueued>0&&game.attackHit<3){game.attackHit++;game.comboQueued--;const id='slash'+game.attackHit;setAnim(id,Math.max(10,(frames[id]||[]).length*4))}else if(['slash1','slash2','slash3'].includes(game.anim)){setAnim('idle')}else if(!['jump','jumpBuster','dash','climb','ready'].includes(game.anim)){setAnim(game.airborne?'jump':'idle')}}}
 if(!game.airborne&&!game.dashTicks&&!game.stateTick&&!game.ladder){if(game.anim==='run'||game.anim==='runBuster'){if(!move)setAnim('idle')}else if(game.anim==='idle'&&held.has('buster'))setAnim('busterIdle');else if(game.anim==='busterIdle'&&!held.has('buster')&&!game.shot)setAnim('idle');else if(game.anim==='ready'&&!game.ready)setAnim('idle')}
 if(game.airborne&&held.has('buster')&&!['airSlash','plunge','risingSlash','risingFall'].includes(game.anim))setAnim('jumpBuster');
 clampPlayer();game.animTick++;pressed.clear();
}

